<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AdminShell from '@/layouts/AdminShell.vue'
import { useAuthStore } from '@/modules/identity/stores/auth'
import http, { getErrorMessage } from '@/api/http'

type Client = { id:string; first_name:string; paternal_last_name:string; maternal_last_name:string; phone:string; email:string; rfc:string|null; street_address:string; neighborhood:string; postal_code:string; state:string; municipality:string; notes:string|null; is_active:boolean; registered_at:string }
const blank=()=>({first_name:'',paternal_last_name:'',maternal_last_name:'',phone:'',email:'',rfc:'',street_address:'',neighborhood:'',postal_code:'',state:'',municipality:'',notes:''})
const clients=ref<Client[]>([]); const form=ref(blank()); const selected=ref<Client|null>(null); const editing=ref(false); const modal=ref(false); const saving=ref(false); const error=ref(''); const success=ref(''); const query=ref(''); const auth=useAuthStore()
const isAdmin=()=>auth.hasRole('administrador_taller')
const filtered=computed(()=>clients.value.filter(c=>`${c.first_name} ${c.paternal_last_name} ${c.email} ${c.phone}`.toLowerCase().includes(query.value.toLowerCase())))
async function load(){try{clients.value=(await http.get<Client[]>('/clients')).data}catch(e){error.value=getErrorMessage(e)}}
function openCreate(){editing.value=false;selected.value=null;form.value=blank();error.value='';modal.value=true}
function openEdit(client:Client){editing.value=true;selected.value=client;form.value={first_name:client.first_name,paternal_last_name:client.paternal_last_name,maternal_last_name:client.maternal_last_name,phone:client.phone,email:client.email,rfc:client.rfc||'',street_address:client.street_address,neighborhood:client.neighborhood,postal_code:client.postal_code,state:client.state,municipality:client.municipality,notes:client.notes||''};error.value='';modal.value=true}
async function save(){saving.value=true;error.value='';success.value='';try{const payload={...form.value,rfc:form.value.rfc||null,notes:form.value.notes||null}; if(editing.value&&selected.value) await http.patch(`/clients/${selected.value.id}`,payload); else await http.post('/clients',payload); success.value=editing.value?'Cliente actualizado correctamente.':'Cliente registrado correctamente.';modal.value=false;await load()}catch(e){error.value=getErrorMessage(e)}finally{saving.value=false}}
async function deactivate(client:Client){if(!confirm(`¿Desactivar a ${client.first_name} ${client.paternal_last_name}? Se conservará su historial.`))return;saving.value=true;try{await http.post(`/clients/${client.id}/deactivate`);success.value='Cliente desactivado correctamente.';await load()}catch(e){error.value=getErrorMessage(e)}finally{saving.value=false}}
onMounted(load)
</script>
<template><AdminShell><section class="client-card"><div class="client-top"><div><p class="eyebrow">Clientes del taller</p><h1>Administrar clientes</h1><p class="subtle">Actualiza su información o desactiva cuentas sin eliminar el historial.</p></div><button class="primary-button" @click="openCreate">＋ Registrar cliente</button></div><p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p><label class="search"><span>⌕</span><input v-model="query" placeholder="Buscar por nombre, correo o teléfono"/></label><div class="table-wrap"><table><thead><tr><th>Cliente</th><th>Contacto</th><th>Registro</th><th>Estado</th><th class="align-right">Acciones</th></tr></thead><tbody><tr v-for="client in filtered" :key="client.id"><td><strong>{{client.first_name}} {{client.paternal_last_name}} {{client.maternal_last_name}}</strong><small>{{client.rfc||'Sin RFC'}}</small></td><td>{{client.email}}<small>{{client.phone}}</small></td><td>{{new Date(client.registered_at).toLocaleDateString('es-MX')}}</td><td><span class="client-status" :class="client.is_active?'active':'inactive'">{{client.is_active?'Activo':'Inactivo'}}</span></td><td class="align-right"><button class="table-action" @click="openEdit(client)">Actualizar</button><button v-if="isAdmin()&&client.is_active" class="table-action danger-action" @click="deactivate(client)">Desactivar</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty-state">No hay clientes registrados en tu taller.</td></tr></tbody></table></div></section><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><section class="modal-card"><div class="modal-title"><div><p class="eyebrow">{{editing?'Actualizar cliente':'Registrar cliente'}}</p><h2>{{editing?'Datos del cliente':'Nuevo cliente'}}</h2></div><button class="close-button" @click="modal=false">×</button></div><form class="client-grid" @submit.prevent="save"><label>Nombre(s)<input v-model.trim="form.first_name" required/></label><label>Apellido paterno<input v-model.trim="form.paternal_last_name" required/></label><label>Apellido materno<input v-model.trim="form.maternal_last_name" required/></label><label>Teléfono<input v-model.trim="form.phone" inputmode="numeric" required/></label><label class="wide">Correo electrónico<input v-model.trim="form.email" type="email" required/></label><label>RFC (opcional)<input v-model.trim="form.rfc" maxlength="13"/></label><label>Calle y número<input v-model.trim="form.street_address" required/></label><label>Colonia<input v-model.trim="form.neighborhood" required/></label><label>Código postal<input v-model.trim="form.postal_code" maxlength="5" required/></label><label>Estado<input v-model.trim="form.state" required/></label><label>Municipio o alcaldía<input v-model.trim="form.municipality" required/></label><label class="full">Notas u observaciones<textarea v-model.trim="form.notes" rows="3"/></label><p v-if="editing&&selected" class="subtle full">Registro original: {{new Date(selected.registered_at).toLocaleDateString('es-MX')}} · Estado: {{selected.is_active?'Activo':'Inactivo'}}</p><div class="client-actions full"><button type="button" class="secondary-button" @click="modal=false">Cancelar</button><button class="primary-button" :disabled="saving">{{saving?'Guardando…':'Guardar cambios'}}</button></div></form></section></div></AdminShell></template>
